#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
    ios::sync_with_stdio(0);
    cin.tie(0);
    long t;
    cin >> t;
    int n;
    while(t--){
        cin >> n;
        int tot_size =n*3;
        vector<long long> a(n*3+1);
        for(int i=1;i<=tot_size;i++) cin >> a[i];
        
        sort(a.begin()+1,a.end());
        vector<long long> p(3*n+1,0);
        for(int i=1;i<=3*n;i++){
            p[i]=p[i-1]+a[i];
        }
        
        auto eval =[&](int z,int k)->long long {
            return 6LL*p[tot_size]-3LL*p[z]-2LL*p[tot_size-k]-p[tot_size-2*z+3*k];
        };
        
        long long strength =0;
        for(int i=0;i<=2*n;i++){
            int l =max(0,i-n);
            int r = i/2;
            
            long long best =eval(i,l);
            
            if(l<r){
                int low =l;
                int high =r-1;
                
                int opt =l;
                
                while(low<=high){
                    int mid = low+(high-low)/2;
                    long long diff =2LL*a[tot_size-mid]-(a[tot_size -2*i+3*mid+1]
                    +a[tot_size  -2*i+3*mid+2]+ a[tot_size -2 *i+3*mid+3]);
                    
                    if(diff>=0){
                        opt =mid+1;
                        low =mid+1;
                    }
                    else{
                        high = mid-1;
                    }
                    
                }
                best = max(best,eval(i,opt));
                if(opt>l)
                  best = max(best,eval(i,opt-1));
                 if(opt<r)
                   best =max(best,eval(i,opt+1));
            }
            strength =max(strength,best);
        }
        cout<<strength<<"\n";
    }
}
